    @Test
    public void testContactViewLayout() {
        navigate("contact");

        // Check heading
        H1 heading = $(H1.class).first();
        assertEquals("Contact", heading.getText());
    }

    @Test
    public void testFormValidation() {
        navigate("contact");

        // Get form fields
        TextField nameField = $(TextField.class).first();
        EmailField emailField = $(EmailField.class).first();
        Button sendButton = $(Button.class).first();

        // Send button should be enabled on empty form
        assertTrue(sendButton.isEnabled());

        // Click send with empty form - should show validation error
        sendButton.click();

        // Check that name field shows error
        assertTrue(nameField.isInvalid());
        assertEquals("Name is required", nameField.getErrorMessage());
    }

    @Test
    public void testSuccessfulSend() {
        navigate("contact");

        // Get form fields
        TextField nameField = $(TextField.class).first();
        EmailField emailField = $(EmailField.class).first();
        TextField phoneField = $(TextField.class).all().get(1);
        TextArea messageField = $(TextArea.class).first();
        Button sendButton = $(Button.class).first();

        // Fill form
        nameField.setValue("John Doe");
        emailField.setValue("john@example.com");
        messageField.setValue("Test message");

        // Send should be enabled
        assertTrue(sendButton.isEnabled());

        // Click send
        sendButton.click();

        // Send button should now be disabled
        assertFalse(sendButton.isEnabled());

        // Form should be cleared
        assertEquals("", nameField.getValue());
        assertEquals("", emailField.getValue());
        assertEquals("", messageField.getValue());
    }

    @Test
    public void testAboutViewExists() {
        navigate("about");

        // Check heading
        H1 heading = $(H1.class).first();
        assertEquals("About", heading.getText());
    }
