+package com.example.views;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.NativeLabel;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import org.springframework.stereotype.Component;
+
+import java.util.ArrayList;
+import java.util.List;
+
+@Route("contact")
+@Component
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final List<Message> messages = new ArrayList<>();
+
+    private TextField nameField;
+    private EmailField emailField;
+    private TextField phoneField;
+    private TextArea messageField;
+    private Button sendButton;
+    private Grid<Message> grid;
+    private boolean isClean = true;
+
+    public ContactView() {
+        setPadding(true);
+        setSpacing(true);
+
+        // Heading
+        H1 heading = new H1("Contact");
+        add(heading);
+
+        // Link to About
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+        add(aboutLink);
+
+        // Form
+        nameField = new TextField("Name");
+        nameField.setWidth("100%");
+        add(nameField);
+
+        emailField = new EmailField("Email");
+        emailField.setWidth("100%");
+        add(emailField);
+
+        phoneField = new TextField("Phone");
+        phoneField.setWidth("100%");
+        add(phoneField);
+
+        messageField = new TextArea("Message");
+        messageField.setWidth("100%");
+        messageField.setHeight("150px");
+        add(messageField);
+
+        sendButton = new Button("Send");
+        add(sendButton);
+
+        // Grid
+        grid = new Grid<>(Message.class, false);
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getMessage).setHeader("Message");
+        grid.setItems(messages);
+        grid.setWidth("100%");
+        add(grid);
+
+        // Track changes
+        nameField.addValueChangeListener(e -> markDirty());
+        emailField.addValueChangeListener(e -> markDirty());
+        phoneField.addValueChangeListener(e -> markDirty());
+        messageField.addValueChangeListener(e -> markDirty());
+
+        sendButton.addClickListener(e -> handleSend());
+    }
+
+    private void markDirty() {
+        if (!hasContent()) {
+            isClean = true;
+        } else {
+            isClean = false;
+        }
+        sendButton.setEnabled(true);
+    }
+
+    private boolean hasContent() {
+        return nameField.getValue().isEmpty() &&
+                emailField.getValue().isEmpty() &&
+                phoneField.getValue().isEmpty() &&
+                messageField.getValue().isEmpty();
+    }
+
+    private void handleSend() {
+        // Clear previous validation errors
+        clearErrors();
+
+        // Validate all fields
+        Message message = new Message();
+        boolean isValid = true;
+
+        // Name validation
+        if (nameField.getValue().trim().isEmpty()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            isValid = false;
+        } else {
+            message.setName(nameField.getValue().trim());
+        }
+
+        // Email validation
+        String emailValue = emailField.getValue().trim();
+        if (!emailValue.isEmpty() && !isValidEmail(emailValue)) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            isValid = false;
+        } else {
+            message.setEmail(emailValue);
+        }
+
+        // Email or phone validation
+        String phoneValue = phoneField.getValue().trim();
+        if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+        message.setPhone(phoneValue);
+
+        // Message validation
+        String messageText = messageField.getValue().trim();
+        if (messageText.isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            isValid = false;
+        } else if (messageText.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            isValid = false;
+        } else {
+            message.setMessage(messageText);
+        }
+
+        if (isValid) {
+            // Add to messages list
+            messages.add(0, message);
+            grid.getDataProvider().refreshAll();
+
+            // Show notification
+            Notification notification = new Notification("Message sent");
+            notification.open();
+
+            // Clear form
+            nameField.setValue("");
+            emailField.setValue("");
+            phoneField.setValue("");
+            messageField.setValue("");
+
+            // Disable Send button
+            sendButton.setEnabled(false);
+            isClean = true;
+        }
+    }
+
+    private boolean isValidEmail(String email) {
+        // Simple email validation
+        return email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
+    }
+
+    private void clearErrors() {
+        nameField.setErrorMessage("");
+        nameField.setInvalid(false);
+
+        emailField.setErrorMessage("");
+        emailField.setInvalid(false);
+
+        phoneField.setErrorMessage("");
+        phoneField.setInvalid(false);
+
+        messageField.setErrorMessage("");
+        messageField.setInvalid(false);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!isClean) {
+            // Show dialog asking if user wants to save
+            Dialog confirmDialog = new Dialog();
+            confirmDialog.setCloseOnOutsideClick(false);
+
+            VerticalLayout dialogLayout = new VerticalLayout();
+            NativeLabel label = new NativeLabel("You have unsaved changes. Do you want to discard them?");
+            dialogLayout.add(label);
+
+            Button keepEditing = new Button("Keep editing", e -> {
+                confirmDialog.close();
+            });
+            Button discard = new Button("Discard", e -> {
+                confirmDialog.close();
+                event.forwardTo("about");
+            });
+
+            dialogLayout.add(keepEditing, discard);
+            confirmDialog.add(dialogLayout);
+            confirmDialog.open();
+
+            event.postpone();
+        }
+    }
+
+    public static class Message {
+        private String name;
+        private String email;
+        private String phone;
+        private String message;
+
+        public String getName() {
+            return name;
+        }
+
+        public void setName(String name) {
+            this.name = name;
+        }
+
+        public String getEmail() {
+            return email;
+        }
+
+        public void setEmail(String email) {
+            this.email = email;
+        }
+
+        public String getPhone() {
+            return phone;
+        }
+
+        public void setPhone(String phone) {
+            this.phone = phone;
+        }
+
+        public String getMessage() {
+            return message;
+        }
+
+        public void setMessage(String message) {
+            this.message = message;
+        }
+    }
+}
